helpers.generate-master-js:
const spec=load("active-model"),src=load("reference-mapping")[spec.id],key=spec.id+"/bengal";
const prompt="Use case: product-mockup. Image 1 is the exact monument design reference for "+spec.id+". Image 2 is only the BENGAL stone reference. Create one clean frontal catalogue master, preserving the complete design and every structural component and proportion. "+spec.masterDescription+" Change "+spec.stoneAreas+" to the exact polished black Bengal granite with natural silver and grey crystalline grain from image 2. "+spec.fixedAreas+" "+spec.removeDescription+" Camera exactly centered on the longitudinal axis, no left or right yaw, main front upright surface parallel to image plane. Use parallel orthographic projection with modest elevation only to reveal the base, no three-quarter view. Entire monument visible with balanced margins. Uniform pale grey studio background and soft contact shadow, gentle light, no glare obscuring surfaces. Do not invent components, text, ornaments, flowers, plants, vases or watermarks. Single square image requested 2048x2048. Fixed geometry master for nine material-only edits.";
store("continuous-prompt:"+key,prompt);
const paths=load("local-texture-paths"),args={prompt,transparent_background:false};
if(paths?.bengal)args.referenced_image_paths=[src.reference_path,paths.bengal];else args.num_last_images_to_include=2;
const task=tools.image_gen__imagegen(args);await yield_control();
const r=await task;store("continuous-generated:"+key,r);
if(!r?.image_url){store("generation-error",{key,result:r});text({key,error:r});throw Error("Generation sans image exploitable");}
spec.masterPath=r.output_hint.match(/\/workspace\/[^\s]+\.png/g).at(-1);store("active-model",spec);
await eval("(async()=>{"+load("journal-generation-js")+"})()");
generatedImage(r);text({key,output_hint:r.output_hint});

helpers.generate-batch-js:
const spec=load("active-model");
const materials=load("generation-batch-materials");
if(!Array.isArray(materials)||materials.length>5||!materials.length)throw Error("Lot invalide");
const paths=load("local-texture-paths");
if(!spec.masterPath||materials.some(mat=>!paths[mat]))throw Error("References locales manquantes");
store("generation-batch-progress",{model:spec.id,materials,completed:[],current:null,finished:false});
for(const mat of materials){
 const key=spec.id+"/"+mat;
 const old=load("continuous-generated:"+key);
 if(old?.image_url||old?.archived)throw Error("Image deja generee: "+key);
 const prompt="Use case: precise-object-edit. Image 1 is the fixed Bengal geometry and framing master for "+spec.geometry+". Image 2 is only the "+mat+" stone reference. Change ONLY "+spec.stoneAreas+" to the exact material of image 2: "+load("material-descriptions")[mat]+". Match natural colors, vein pattern and realistic grain size, polished surface with gentle highlights. "+spec.fixedAreas+" Preserve exactly every structural component, silhouette, thickness, opening, joint, crop, camera, scale, pale grey background and soft contact shadows. "+(spec.extraConstraints??"")+" Do not add parts, engraving, text, optional decoration, flowers, plants, vases, logos or watermarks. One single square image requested 2048x2048.";
 store("continuous-prompt:"+key,prompt);
 const state=load("generation-batch-progress");state.current=mat;store("generation-batch-progress",state);
 const task=tools.image_gen__imagegen({prompt,transparent_background:false,referenced_image_paths:[spec.masterPath,paths[mat]]});
 await yield_control();
 let r;
 try { r=await task; } catch(e) {
  const failure={key,error:String(e)};
  store("generation-error",failure);const failed=load("generation-batch-progress");failed.error=failure;store("generation-batch-progress",failed);text(failure);break;
 }
 store("continuous-generated:"+key,r);
 if(!r?.image_url){store("generation-error",{key,result:r});text({key,error:r});const failed=load("generation-batch-progress");failed.error={key,result:r};store("generation-batch-progress",failed);break;}
 const st=load("generation-batch-progress");st.completed.push(mat);st.current=null;store("generation-batch-progress",st);
 await eval("(async()=>{"+load("journal-generation-js")+"})()");
generatedImage(r);text({key,output_hint:r.output_hint,batchComplete:st.completed.length,batchTarget:materials.length});
 await yield_control();
}
const st=load("generation-batch-progress");st.finished=st.completed.length===materials.length;store("generation-batch-progress",st);
text({batchFinished:st.finished,model:spec.id,materials,completed:st.completed,error:st.error??null});

helpers.archive-one-js:
const key=load("current-image-key");
const opts=load("current-image-options");
const r=load("continuous-generated:"+key);
const path=r.output_hint.match(/\/workspace\/[^\s]+\.png/g).at(-1);
const sq=s=>"'"+s.replace(/'/g,"'\\''")+"'";
const py="import hashlib,json,pathlib,struct,sys\np=pathlib.Path(sys.argv[1]); b=p.read_bytes()\nprint(json.dumps({'path':str(p),'sha256':hashlib.sha256(b).hexdigest(),'total':len(b),'dimensions':list(struct.unpack('>II',b[16:24]))}))";
let mres;
try { mres=await tools.exec_command({cmd:"python -c "+sq(py)+" "+sq(path),max_output_tokens:500}); }
catch(e) {
 if(!String(e).includes("transport disconnected"))throw e;
 mres=await tools.exec_command({cmd:"python -c "+sq(py)+" "+sq(path),max_output_tokens:500});
}
const m=JSON.parse(mres.output.trim());
store("continuous-metadata:"+key,m);
const base={modeleId:opts.model,matiereId:opts.material,destination:"pilotes/"+opts.family+"/"+opts.model+"/v1/"+opts.model+"-"+opts.material+".png",sha256:m.sha256,total:m.total,prompt:load("continuous-prompt:"+key),references:opts.references,sourceLocale:path,controleVisuel:opts.review};
store("continuous-transfer-base:"+key,base);
const b64=r.image_url.split(",")[1],pid=load("productionReceiver");

for(let start=0;start<b64.length;start+=1024000){
 const sent=await tools.mcp__codex_apps__vps_proxy_interact_with_process({pid,input:JSON.stringify({...base,offset:start/4*3,data:b64.slice(start,start+1024000)}),wait_for_prompt:false,timeout_ms:1000});
 if(sent.isError)throw Error("Erreur envoi du bloc "+start+"; controler le dernier accuse avant reprise.");
 store("continuous-sent:"+key,Math.min(base.total,(start+1024000)/4*3));
}
let success=false;
for(let attempt=0;attempt<4;attempt++){
 const ack=await tools.mcp__codex_apps__vps_proxy_read_process_output({pid,offset:-4,length:4,timeout_ms:1000});
 const raw=ack.content?.filter(x=>x.type==="text").map(x=>x.text).join("\n")??"";
 const last=raw.split("\n").filter(x=>x.startsWith("{")).map(x=>JSON.parse(x)).at(-1);
 if(ack.isError||last?.ok===false)throw Error(raw);
 if(last?.archive?.endsWith(base.destination)){store("continuous-ack:"+key,last);store("continuous-completed",last.imagesCompletes);text({key,total:last.imagesCompletes,archive:last.archive});success=true;break;}
}
if(!success)throw Error("Archivage non confirme; controler le dernier accuse et le fichier avant reprise.");

store('continuous-generated:'+key,{output_hint:r.output_hint,archived:true,path});

helpers.archive-batch-js:
const spec=load("active-model"), mats=load("archive-batch-materials");
if(!Array.isArray(mats)||mats.length>5||mats.length<1)throw Error("Lot archivage invalide");
for(const mat of mats){
 const key=spec.id+"/"+mat,review=load("continuous-review:"+key);
 if(!review)throw Error("Controle visuel manquant pour "+key);
 store("current-image-key",key);
 store("current-image-options",{model:spec.id,material:mat,family:spec.family,references:mat==="bengal"?[load("reference-mapping")[spec.id].library_file_id,"bengal-texture-v1.png"]:[spec.id+"-bengal.png",mat+"-texture-v1.png"],review});
 await eval("(async()=>{"+load("archive-one-js")+"})()");
 await yield_control();
}
text({archiveBatchFinished:true,model:spec.id,materials:mats,total:load("continuous-completed")});

helpers.journal-generation-js:
const journalPath=r.output_hint.match(/\/workspace\/[^\s]+\.png/g).at(-1);
const journalData={key,model:spec.id,material:key.split("/")[1],prompt,path:journalPath,masterPath:spec.masterPath||journalPath,createdAt:new Date().toISOString()};
const journalPy="import json,pathlib,sys\nd=json.loads(sys.argv[1]);p=pathlib.Path('/workspace/scratch/fc8dfd468718/production-journal')/(d['key']+'.json');p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\\n')";
const journalSq=s=>"'"+s.replace(/'/g,"'\\''")+"'";
const journalResult=await tools.exec_command({cmd:"python3 -c "+journalSq(journalPy)+" "+journalSq(JSON.stringify(journalData)),max_output_tokens:100});
if(journalResult.exit_code!==0)throw Error("Journal local non sauvegarde: "+journalResult.output);
